# ORF finding in all 6 frames
def orfs(s, minaa=50, name="+"):
    out=[]
    n=len(s)
    for frame in range(3):
        i=frame
        while i < n-2:
            if s[i:i+3]=="ATG":
                j=i
                while j < n-2:
                    cod=s[j:j+3]
                    if cod in ("TAA","TAG","TGA"):
                        break
                    j+=3
                if (j-i)//3 >= minaa:
                    out.append((i,j+3,(j-i)//3,name))
                i=j if j>i else i+3
            else:
                i+=3
    return out

allorfs = orfs(seq, minaa=50, name="+") + orfs(rc(seq), minaa=50, name="-")
allorfs.sort(key=lambda x:-x[2])
print("ORFs >=50 aa:")
for o in allorfs:
    print(o)

import random
seq = ""
with open("region.fasta") as f:
    for line in f:
        if not line.startswith(">"):
            seq += line.strip()

def rc(s): return s.translate(str.maketrans("ACGT","TGCA"))[::-1]
def longest_orf_randomized(seq, reps=200):
    bases=list(seq)
    def orfmax(s):
        n=len(s); best=0
        for frame in range(3):
            i=frame
            while i<n-2:
                if s[i:i+3]=="ATG":
                    j=i
                    while j<n-2 and s[j:j+3] not in ("TAA","TAG","TGA"):
                        j+=3
                    best=max(best,(j-i)//3)
                    i=j if j>i else i+3
                else: i+=3
        return best
    tot=0
    for _ in range(reps):
        random.shuffle(bases)
        r="".join(bases)
        tot+=max(orfmax(r), orfmax(rc(r)))
    return tot/reps

